void qb_file_open_legacy(int32_t fnum, const char* mode_char, const char* fname) {
    if (!mode_char || !fname) return;
    // Convert legacy mode character to standard mode string
    const char* mode;
    switch (mode_char[0]) {
        case 'I': case 'i': mode = "r"; break;
        case 'O': case 'o': mode = "w"; break;
        case 'A': case 'a': mode = "a"; break;
        case 'R': case 'r': mode = "r+b"; break;
        case 'B': case 'b': mode = "r+b"; break;
        default: mode = "r"; break;
    }
    qb_file_open(fnum, fname, mode);
}

