qb_string* qb_readfile(qb_string* path) {
    if (!path) return qb_string_empty();
    const char* path_str = qb_string_data(path);
    FILE* f = fopen(path_str, "rb");
    if (!f) return qb_string_empty();
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char* buf = (char*)malloc(size + 1);
    if (!buf) { fclose(f); return qb_string_empty(); }
    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);
    qb_string* result = qb_string_from_bytes((uint8_t*)buf, size);
    free(buf);
    return result;
}

void qb_writefile(qb_string* path, qb_string* content) {
    if (!path || !content) return;
    const char* path_str = qb_string_data(path);
    const char* content_data = qb_string_data(content);
    size_t content_len = qb_string_len(content);
    FILE* f = fopen(path_str, "wb");
    if (!f) return;
    fwrite(content_data, 1, content_len, f);
    fclose(f);
}

